from typing import Any
from typing import TextIO
import csv
import io
REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def xlsx_to_csv_text(data: bytes, max_rows: int = MAX_ROWS) -> str:
    """Convert the first sheet of an xlsx file to CSV text, keeping row numbers aligned."""
    from openpyxl import load_workbook

    workbook = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
    try:
        sheet = workbook.worksheets[0]
        out = io.StringIO()
        writer = csv.writer(out)
        # +2 allows the header row plus one row beyond the cap so import_users flags it
        for row in sheet.iter_rows(min_row=1, max_row=max_rows + 2, values_only=True):
            cells = []
            for value in row:
                text = '' if value is None else str(value)
                # keep one spreadsheet row per CSV line so reported row numbers match
                cells.append(text.replace('\r', ' ').replace('\n', ' '))
            writer.writerow(cells)
        return out.getvalue()
    finally:
        workbook.close()


def validate_users_upload(filename: str, content: bytes, max_rows: int = MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users export (.xlsx or .csv).

    Returns {"valid_users": [...], "invalid_rows": [{"row": n, "errors": [...]}, ...],
    "valid_count": int, "invalid_count": int}. Every row is checked; validation does
    not stop at the first error. Row numbers are spreadsheet/file line numbers
    (the header is row 1).
    """
    name = (filename or '').lower().strip()
    try:
        if name.endswith('.xlsx'):
            text = xlsx_to_csv_text(content, max_rows)
        elif name.endswith('.csv'):
            try:
                text = content.decode('utf-8-sig')
            except UnicodeDecodeError:
                text = content.decode('latin-1')
        else:
            invalid = [{'row': 0, 'errors': ['unsupported file type; upload .xlsx or .csv']}]
            return {'valid_users': [], 'invalid_rows': invalid, 'valid_count': 0, 'invalid_count': 1}
        valid, errors = import_users(text, max_rows)
    except Exception:
        invalid = [{'row': 0, 'errors': ['file could not be read; check it is a valid .xlsx or .csv']}]
        return {'valid_users': [], 'invalid_rows': invalid, 'valid_count': 0, 'invalid_count': 1}
    return {
        'valid_users': valid,
        'invalid_rows': errors,
        'valid_count': len(valid),
        'invalid_count': len(errors),
    }

